import java.io.InputStreamReader

val content = """
THINK DEEPLY:
  Analyze this network scan result for anomalies:
  {
    "target": "127.0.0.1",
    "openPorts": [135, 445],
    "timestamp": "2026-05-10T23:38:12.945Z",
    "scanMethod": "native-net"
  }
"""

val parser = KJsonParser()
val objectMapper = ObjectMapper().apply {
  def writeObjectToJson(input: Any) =
    try
      json(input.toString)
    catch
      .finally { }
}

object MyAgent extends RecursiveAction {
  override val actionClass: Class[_] = classOf[MyAgent]

  val parserFn: Parser[String] = objectMapper.apply {
    def writeObjectToJson(input: Any) =
      try
        json(input.toString)
      catch finally {}
  }

  override def process(context: ActionContext): Future[Result] = {
    val result = context.read().readAsOpt[KJsonTree].map { tree =>
      val parsedContent = parser.parse(json(content))
      val scan = parsedContent.get("target")
      if (scan.isEmpty) {
        Some(Result.Success(tree))
      } else {
        Some(Result.AnomalyResult(scan, "Anomaly in the scan data"))
      }
    }

    result.flatMap(result => context.success(result))
  }
}
